public sealed record ProjectMediaReplacementItemResponse(Guid FileAssetId,int SortOrder,bool IsCover,string? Caption){public static ProjectMediaReplacementItemResponse From(CompanyProjectMedia x)=>new(x.FileAssetId,x.SortOrder,x.IsCover,x.Caption);}
