public sealed record ProjectNearbyPlaceResponse(Guid Id,string Category,string Name,decimal? DistanceMeters,int? TravelMinutes,decimal? Latitude,decimal? Longitude){public static ProjectNearbyPlaceResponse From(CompanyProjectNearbyPlace x)=>new(x.Id,x.Category,x.Name,x.DistanceMeters,x.TravelMinutes,x.Latitude,x.Longitude);}
